<script setup lang="ts">
import { computed, nextTick, onMounted, onBeforeUnmount, ref, watch } from 'vue'
import Icon from './components/Icon.vue'
import SnapMindLogo from './components/SnapMindLogo.vue'
import FloatingScreenshot from './components/FloatingScreenshot.vue'
import FormulaResult from './components/FormulaResult.vue'
import TableResult from './components/TableResult.vue'
import ScreenshotLauncher from './components/ScreenshotLauncher.vue'
import CaptureOverlay from './components/CaptureOverlay.vue'
import { grabScreen, readCaptureFile, type CaptureResult } from './capture'
import './screenshot.css'
import './floating.css'
import { api } from './api'
import { newSession, uid, withoutDemoData } from './sessions'
import type { Asset, Scenario, Session } from './types'
import {native,desktopRole,desktop} from './desktop'


import './model-settings.css'
import {captureShortcut,shortcutFromEvent} from './shortcut'
import {tx} from './preferences'
import {modelRegistry,loadModels} from './models'
const activeModelName=computed(()=>modelRegistry.value.profiles.find(p=>p.id===modelRegistry.value.activeId)?.model||'')

const sessions=ref<Session[]>([]),activeId=ref(''),assetId=ref(''),search=ref(''),draft=ref(''),loading=ref(true),busy=ref(false),streamText=ref(''),online=ref(false),saving=ref(false),saveError=ref(false),modal=ref(''),toast=ref(''),menu=ref(''),editTitle=ref(''),targetId=ref(''),leftWidth=ref(38),dragging=ref(false),galleryFilter=ref('all'),dropActive=ref(false)
const fileInput=ref<HTMLInputElement>(),messageList=ref<HTMLElement>(),workspace=ref<HTMLElement>()
const view=ref<'launcher'|'workspace'>(desktopRole==='workspace'?'workspace':'launcher'),captureSource=ref<Asset>(),floatingPreview=ref(false),capturing=ref(false),captureInput=ref<HTMLInputElement>(),pinned=ref<Asset>(),pinPosition=ref({x:Math.min(window.innerWidth-380,window.innerWidth/2+100),y:120})
const desktopDisposers:(()=>void)[]=[]
let desktopTasks=Promise.resolve(),desktopLoading=false
async function receiveDesktopCapture(payload:{asset:Asset;action:string;notice?:string}){
 const runtime=await desktop.state();try{sessions.value=await api.list()}catch{try{sessions.value=JSON.parse(localStorage.getItem('snapmind-sessions')||'[]')}catch{}}
 let s=sessions.value.find(s=>s.id===runtime.sessionId&&s.assets.length<20);if(!s){s=newSession();s.title='截图 '+new Intl.DateTimeFormat('zh-CN',{hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false,timeZone:'Asia/Shanghai'}).format(new Date());sessions.value.unshift(s)}
 s.assets.push(payload.asset);chooseSession(s);assetId.value=payload.asset.id;persist(s);await saveQueue
 await desktop.session(s.id,JSON.parse(JSON.stringify(payload.asset)),undefined,false)
 if(payload.action==='save')await desktop.save();if(payload.notice)notify(payload.notice)
}
async function loadDesktopSession(sessionId?:string,action?:string){desktopLoading=true;try{try{sessions.value=await api.list();online.value=true}catch{online.value=false;try{sessions.value=JSON.parse(localStorage.getItem('snapmind-sessions')||'[]')}catch{}}const s=sessions.value.find(s=>s.id===sessionId);if(s)chooseSession(s);view.value='workspace';showContentWorkspace.value=true;showFloatingImage.value=false;await nextTick();if(action)quickAction(action,action==='explain'?'AI 解释':'处理')}finally{desktopLoading=false}}
async function setupDesktopHooks(){if(!native)return;if(desktopRole==='main'){desktopDisposers.push(await desktop.listen<{asset:Asset;action:string;notice?:string}>('desktop:capture-finished',payload=>{desktopTasks=desktopTasks.then(()=>receiveDesktopCapture(payload)).catch(e=>notify('桌面截图处理失败：'+String(e)))}));desktopDisposers.push(await desktop.listen<string>('desktop:error',notify));desktopDisposers.push(await desktop.listen<string>('desktop:launcher-action',launcherAction));desktopDisposers.push(await desktop.onFocus(focused=>{if(focused&&!loading.value){refreshGallery();loadModels().catch(()=>{})}else if(!focused&&['settings','model-settings','shortcut'].includes(modal.value))modal.value=''}))}else if(desktopRole==='workspace'){desktopDisposers.push(await desktop.listen<{sessionId:string;action?:string;assetId?:string}>('desktop:session-ready',async payload=>{await loadDesktopSession(payload.sessionId);await nextTick();await new Promise<void>(r=>requestAnimationFrame(()=>requestAnimationFrame(()=>r())));if(payload.assetId)await desktop.contentReady(payload.assetId);if(payload.action)quickAction(payload.action,payload.action==='explain'?'AI '+String.fromCharCode(0x89e3,0x91ca):String.fromCharCode(0x5904,0x7406))}))} }
const recentCaptures=computed(()=>[...sessions.value].sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)).flatMap(s=>[...s.assets].reverse()).filter(a=>a.scenario==='custom'))
const desktopSource=ref<Asset>(),showFloatingImage=ref(true),showContentWorkspace=ref(true),floatImage=ref({x:35,y:110,width:500}),floatWork=ref({x:565,y:110,width:680,height:650})
let workDrag=false,workStart={x:0,y:0},workOrigin={x:0,y:0},editingCaptureId=''
function arrangeFloating(){const w=window.innerWidth,h=window.innerHeight,ratio=asset.value?asset.value.width/asset.value.height:1.4;const workWidth=Math.min(720,Math.max(450,w*.47)),top=Math.max(90,Math.min(155,h*.145));const imageWidth=Math.max(220,Math.min(560,w-workWidth-78,(h-top-130)*ratio));const x=Math.max(20,(w-imageWidth-workWidth-22)/2);floatImage.value={x,y:top,width:imageWidth};floatWork.value={x:x+imageWidth+22,y:top,width:workWidth,height:Math.max(430,Math.min(740,h-top-65))}}
function workDown(e:PointerEvent){if((e.target as Element).closest('button'))return;if(native){desktop.drag();return}workDrag=true;workStart={x:e.clientX,y:e.clientY};workOrigin={x:floatWork.value.x,y:floatWork.value.y};(e.currentTarget as HTMLElement).setPointerCapture(e.pointerId)}
function workMove(e:PointerEvent){if(!workDrag)return;floatWork.value.x=Math.max(0,Math.min(innerWidth-100,workOrigin.x+e.clientX-workStart.x));floatWork.value.y=Math.max(10,Math.min(innerHeight-80,workOrigin.y+e.clientY-workStart.y))}
function openContent(action='open'){showContentWorkspace.value=true;if(action!=='open')quickAction(action,action==='explain'?'AI 解释':'处理')}
function annotateFloating(){if(!asset.value)return;editingCaptureId=asset.value.id;captureSource.value=asset.value;modal.value=''}
function cancelCapture(){captureSource.value=undefined;floatingPreview.value=false;editingCaptureId=''}
function saveFloating(){if(!asset.value)return;const a=document.createElement('a');a.href=asset.value.data;a.download=asset.value.name+'.png';a.click();notify('已保存截图')}
async function copyFloating(){if(!asset.value)return;try{const blob=await(await fetch(asset.value.data)).blob();await navigator.clipboard.write([new ClipboardItem({[blob.type]:blob})]);notify('截图已复制')}catch{notify('浏览器未允许复制，请使用保存按钮')}}
let pinStart={x:0,y:0},pinOrigin={x:0,y:0},pinDragging=false
function pinDown(e:PointerEvent){if((e.target as HTMLElement).closest('button'))return;pinDragging=true;pinStart={x:e.clientX,y:e.clientY};pinOrigin={...pinPosition.value};(e.currentTarget as HTMLElement).setPointerCapture(e.pointerId)}
function pinMove(e:PointerEvent){if(pinDragging)pinPosition.value={x:Math.max(0,Math.min(window.innerWidth-100,pinOrigin.x+e.clientX-pinStart.x)),y:Math.max(0,Math.min(window.innerHeight-40,pinOrigin.y+e.clientY-pinStart.y))}}
function returnHome(){if(busy.value){notify('请先停止当前生成');return}if(native&&desktopRole==='workspace'){desktop.launcher();desktop.hide();return}view.value='launcher';modal.value=''}
function closeContent(){if(native)desktop.hide();else showContentWorkspace.value=false}
async function beginScreenCapture(){if(capturing.value||captureSource.value)return;modal.value='';floatingPreview.value=false;capturing.value=true;try{if(native)await desktop.capture();else{captureSource.value=await grabScreen();}}catch(e){notify((e as Error).name==='NotAllowedError'?'已取消截图授权':String(e))}finally{capturing.value=false}}
async function openCaptureFiles(files:FileList|null){if(!files?.length)return;floatingPreview.value=false;try{const a=await readCaptureFile(files[0]!);if(native)await desktop.preview(a);else{captureSource.value=a;}modal.value=''}catch(e){notify(String(e))}if(captureInput.value)captureInput.value.value=''}
async function completeCapture(result:CaptureResult){const source=captureSource.value!;captureSource.value=undefined;floatingPreview.value=false;const editing=active.value?.assets.find(a=>a.id===editingCaptureId);editingCaptureId='';const a:Asset=editing||{id:uid(),name:source.name,data:result.data,width:result.width,height:result.height,scenario:'custom'};if(editing)Object.assign(a,{data:result.data,width:result.width,height:result.height});else desktopSource.value=source;const s=view.value==='workspace'&&active.value&&active.value.assets.length<20?active.value:newSession();if(!sessions.value.includes(s)){s.title='截图 '+new Intl.DateTimeFormat('zh-CN',{hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false,timeZone:'Asia/Shanghai'}).format(new Date());sessions.value.unshift(s)}if(!editing)s.assets.push(a);chooseSession(s);assetId.value=a.id;s.scenario='custom';persist(s);view.value='launcher';if(result.action==='pin')pinned.value=a;await nextTick();if(result.action==='save')notify('截图已保存');else if(result.action==='pin')notify('截图已浮动显示，可拖动与缩放');else notify(result.copied?'截图已复制，可直接 Ctrl+V 粘贴':'截图已浮动显示；浏览器未允许复制')}
async function preview(a:Asset){if(capturing.value||captureSource.value)return;modal.value='';if(native){capturing.value=true;try{await desktop.preview(a,true)}catch{notify('无法打开图片，请重试。')}finally{capturing.value=false}}else{floatingPreview.value=true;captureSource.value=a;editingCaptureId=''}}
const active=computed(()=>sessions.value.find(s=>s.id===activeId.value))
const asset=computed(()=>active.value?.assets.find(a=>a.id===assetId.value)||active.value?.assets[0])
watch(()=>asset.value?.id,()=>{showFloatingImage.value=true;nextTick(arrangeFloating)})
watch(()=>[activeId.value,asset.value?.id],()=>{if(native&&desktopRole==='workspace'&&initialized&&!desktopLoading&&active.value)desktop.session(active.value.id,asset.value?JSON.parse(JSON.stringify(asset.value)):undefined,undefined,false).catch(e=>notify(String(e)))})
const filtered=computed(()=>sessions.value.filter(s=>s.title.toLowerCase().includes(search.value.toLowerCase())).sort((a,b)=>Number(b.pinned)-Number(a.pinned)||b.updatedAt.localeCompare(a.updatedAt)))
const gallery=computed(()=>sessions.value.flatMap(s=>s.assets.map(a=>({session:s,asset:a}))).filter(i=>(view.value==='workspace'||i.asset.scenario==='custom')&&(galleryFilter.value==='all'||i.asset.scenario===galleryFilter.value)))
const actions=[{id:'translate',label:'翻译',icon:'translate'},{id:'ocr',label:'提取文字',icon:'ocr'}]
const suggestions=computed(()=>active.value?.scenario==='table'?['提取表格并绘图','这些数据说明了什么？']:active.value?.scenario==='error'?['解释这个报错','如何检查 Python 环境？']:['为什么要做缩放？','Q、K、V 分别是什么？'])
const assetLabel=computed(()=>asset.value?.scenario==='formula'?'论文阅读':asset.value?.scenario==='table'?'办公数据':asset.value?.scenario==='error'?'报错排查':'图片素材')
let controller:AbortController|undefined,saveTimer:ReturnType<typeof setTimeout>|undefined,toastTimer:ReturnType<typeof setTimeout>|undefined,saveQueue=Promise.resolve(),initialized=false
function notify(message:string){toast.value=message;if(toastTimer)clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value='',3200)}
function localSave(){try{localStorage.setItem('snapmind-sessions',JSON.stringify(sessions.value));saveError.value=false}catch{saveError.value=true;notify('本地缓存空间不足，请启动后端保存会话。')}}
function persist(s:Session){const snapshot=JSON.parse(JSON.stringify(s)) as Session;if(!online.value){localSave();return}saveQueue=saveQueue.then(async()=>{saving.value=true;try{await api.save(snapshot);saveError.value=false}catch{saveError.value=true;notify('会话保存失败，请检查后端连接。')}finally{saving.value=false}})}
watch(()=>active.value?JSON.stringify({...active.value,updatedAt:''}):'',()=>{if(!initialized||busy.value||!active.value)return;if(saveTimer)clearTimeout(saveTimer);saveTimer=setTimeout(()=>{saveTimer=undefined;if(active.value){active.value.updatedAt=new Date().toISOString();persist(active.value)}},450)})
watch(activeId,id=>{localStorage.setItem('snapmind-active',id);nextTick(()=>{if(messageList.value)messageList.value.scrollTop=0})})
function scrollDown(){if(messageList.value)messageList.value.scrollTop=messageList.value.scrollHeight}
function chooseSession(s:Session){if(busy.value){notify('请先等待回复完成，或停止生成');return}if(saveTimer){clearTimeout(saveTimer);saveTimer=undefined;if(active.value)persist(active.value)}activeId.value=s.id;assetId.value=s.assets[0]?.id||'';draft.value='';menu.value=''}
function createSession(scenario:Scenario='custom'){if(busy.value){notify('请先停止当前生成');return}const s=newSession(scenario);sessions.value.unshift(s);chooseSession(s);persist(s);modal.value=''}
async function importFiles(files:FileList|File[]|null){if(!files)return;if(!active.value)createSession();let added=0;const session=active.value!;for(const f of Array.from(files)){if(!['image/png','image/jpeg','image/webp'].includes(f.type)){notify('请选择 PNG、JPG 或 WebP 图片');continue}if(f.size>8*1024*1024){notify('单张图片不能超过 8 MB');continue}if(session.assets.length>=20){notify('每个会话最多 20 张截图');break}try{const data=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result as string);reader.onerror=reject;reader.readAsDataURL(f)});const img=new Image();img.src=data;await img.decode();if(img.width>20000||img.height>20000){notify('图片尺寸过大，请缩小后导入');continue}if(session.assets.reduce((sum,a)=>sum+a.data.length,0)+data.length>36_000_000){notify('当前会话素材已达上限，请新建会话');break}const a:Asset={id:uid(),name:f.name,data,width:img.width,height:img.height,scenario:'custom'};session.assets.push(a);assetId.value=a.id;session.scenario='custom';if(session.title==='新的截图会话')session.title=f.name.replace(/\.[^.]+$/,'');added++}catch{notify('图片无法读取，请换一张图片')}}if(added){persist(session);notify(`已添加 ${added} 张图片`)}if(fileInput.value)fileInput.value.value='';modal.value=''}
function paste(e:ClipboardEvent){const files=e.clipboardData?.files;if(files?.length){e.preventDefault();if(view.value==='launcher')openCaptureFiles(files);else importFiles(files)}}
function drop(e:DragEvent){e.preventDefault();dropActive.value=false;importFiles(e.dataTransfer?.files||null)}
function changeImage(data:string,width:number,height:number){if(!asset.value)return;Object.assign(asset.value,{data,width,height});persist(active.value!)}
async function send(action='chat',prompt?:string){if(busy.value||!active.value)return;if(!active.value.assets.length){notify('先添加一张截图，再开始讨论');return}const text=(prompt||draft.value).trim();if(!text)return;if(text.length>6000){notify('每条消息最多 6000 个字符');return}if(!online.value){notify('后端未连接，请启动 Python 服务后重试');return}if(saveTimer){clearTimeout(saveTimer);saveTimer=undefined}const s=active.value;s.messages.push({id:uid(),role:'user',text,action,sources:s.assets.map(a=>a.id)});draft.value='';busy.value=true;streamText.value='';controller=new AbortController();await nextTick();scrollDown();try{await saveQueue;const message=await api.chat(JSON.parse(JSON.stringify(s)),action,text,controller.signal,chunk=>{streamText.value+=chunk;nextTick(scrollDown)});s.messages.push(message)}catch(e){if((e as Error).name==='AbortError')notify('已停止生成');else notify((e as Error).message)}finally{busy.value=false;streamText.value='';s.updatedAt=new Date().toISOString();persist(s);nextTick(scrollDown)}}
function quickAction(id:string,label:string){send(id,id==='formula'?'提取并解释这张截图中的公式。':id==='table'?'将截图中的表格转成可编辑数据并绘图。':id==='translate'?'把这张截图的正文翻译成中文。':id==='ocr'?'提取截图中的文字。':`请${label}这张截图的内容。`)}
async function copyText(text:string){try{await navigator.clipboard.writeText(text);notify('已复制')}catch{notify('剪贴板访问被浏览器限制')}}
function sourceName(id:string){return active.value?.assets.find(a=>a.id===id)?.name||'截图素材'}
function exportSession(){if(!active.value)return;const s=active.value;const text=`# ${s.title}\n\n> SnapMind 会话记录\n\n`+s.messages.map(m=>`## ${m.role==='user'?'我':'SnapMind'}\n\n${m.text}\n\n${m.kind==='formula'?'```latex\n'+s.formula+'\n```\n':m.kind==='table'?s.rows.map(r=>`${r.label}: ${r.value}`).join('\n')+'\n':''}`).join('\n');const url=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=s.title+'.md';a.click();URL.revokeObjectURL(url);notify('会话已导出为 Markdown')}
function openRename(s:Session){targetId.value=s.id;editTitle.value=s.title;modal.value='rename';menu.value=''}
function rename(){const s=sessions.value.find(s=>s.id===targetId.value);if(!s||!editTitle.value.trim())return;s.title=editTitle.value.trim();persist(s);modal.value=''}
function confirmDelete(s:Session){targetId.value=s.id;modal.value='delete';menu.value=''}
async function remove(){const s=sessions.value.find(s=>s.id===targetId.value);if(!s)return;try{if(saveTimer){clearTimeout(saveTimer);saveTimer=undefined}await saveQueue;if(online.value)await api.remove(s.id);sessions.value=sessions.value.filter(i=>i.id!==s.id);if(activeId.value===s.id){if(!sessions.value.length)createSession();else chooseSession(sessions.value[0]!)}if(!online.value)localSave();modal.value='';notify('会话已删除')}catch{notify('删除失败，请检查服务连接')}}
function pin(s:Session){s.pinned=!s.pinned;persist(s);menu.value=''}
function startDrag(e:PointerEvent){if(window.innerWidth<1000)return;dragging.value=true;(e.target as HTMLElement).setPointerCapture(e.pointerId)}
function moveDrag(e:PointerEvent){if(!dragging.value||!workspace.value)return;const rect=workspace.value.getBoundingClientRect();leftWidth.value=Math.min(49,Math.max(29,(e.clientX-rect.left)/rect.width*100))}
function endDrag(){dragging.value=false;localStorage.setItem('snapmind-left-width',String(leftWidth.value))}
function dateLabel(date:string){const n=new Date(),d=new Date(date);if(d.toDateString()===n.toDateString())return '今天';n.setDate(n.getDate()-1);if(d.toDateString()===n.toDateString())return '昨天';return new Intl.DateTimeFormat('zh-CN',{month:'short',day:'numeric'}).format(d)}
function sessionIcon(s:Session){return s.scenario==='table'?'table':s.scenario==='error'?'terminal':s.scenario==='custom'?'images':'book'}
function selectGallery(s:Session,a:Asset){if(view.value==='launcher'){preview(a);return}chooseSession(s);assetId.value=a.id;modal.value=''}
let previousFocus:HTMLElement|null=null
watch(modal,async(value,old)=>{if(value&&!old)previousFocus=document.activeElement as HTMLElement;await nextTick();if(value){const dialog=document.querySelector('.modal') as HTMLElement|null;const input=dialog?.querySelector<HTMLInputElement>('input');(input||dialog)?.focus()}else previousFocus?.focus()})
function keydown(e:KeyboardEvent){if(captureSource.value)return;if(e.key==='Escape'){modal.value='';menu.value=''}if(e.key==='Tab'&&modal.value){const dialog=document.querySelector('.modal');const focusable=Array.from(dialog?.querySelectorAll<HTMLElement>('button:not(:disabled),input,textarea,[tabindex="0"]')||[]);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===dialog)){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}if(!native&&shortcutFromEvent(e)===captureShortcut.value){e.preventDefault();beginScreenCapture()}if(view.value==='launcher'&&(e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='o'){e.preventDefault();captureInput.value?.click()}}
async function reconnect(){try{await api.health();online.value=true;for(const s of sessions.value)persist(s);notify('本地服务已连接')}catch{notify('服务仍未连接，请运行后端启动命令')}}
const modelSettingsRequest=ref(0)
const shortcutSettingsRequest=ref(0)
const refreshingGallery=ref(false)
async function refreshGallery(){if(refreshingGallery.value)return;refreshingGallery.value=true;try{if(saveTimer){clearTimeout(saveTimer);saveTimer=undefined;if(active.value)persist(active.value)}await saveQueue;const stored=await api.list();sessions.value=stored;online.value=true;if(!sessions.value.some(s=>s.id===activeId.value)){activeId.value=sessions.value[0]?.id||'';assetId.value=active.value?.assets[0]?.id||''}}catch{notify('图片刷新失败，请检查本地服务连接')}finally{refreshingGallery.value=false}}
function mergeStored(stored:Session[]){const ids=new Set(sessions.value.map(s=>s.id));sessions.value=[...sessions.value,...stored.map(withoutDemoData).filter((s):s is Session=>!!s&&!ids.has(s.id))]}
async function launcherAction(action:string){view.value='launcher';if(action==='model-settings'){modal.value='';modelSettingsRequest.value++;return}if(action==='shortcut'){modal.value='';shortcutSettingsRequest.value++;return}if(action==='gallery'){await refreshGallery();galleryFilter.value='all';modal.value='gallery'}else if(action==='settings')modal.value=action;else modal.value=''}
onMounted(async()=>{await setupDesktopHooks();await loadModels().catch(()=>{});document.addEventListener('paste',paste);document.addEventListener('keydown',keydown);window.addEventListener('resize',arrangeFloating);leftWidth.value=Math.min(49,Math.max(29,Number(localStorage.getItem('snapmind-left-width'))||38));try{await api.health();online.value=true;mergeStored(await api.list());}catch{online.value=false;try{mergeStored(JSON.parse(localStorage.getItem('snapmind-sessions')||'[]'))}catch{}}const previous=localStorage.getItem('snapmind-active');activeId.value=sessions.value.find(s=>s.id===activeId.value)?.id||sessions.value.find(s=>s.id===previous)?.id||sessions.value.find(s=>s.pinned)?.id||sessions.value[0]?.id||'';assetId.value=assetId.value||active.value?.assets[0]?.id||'';loading.value=false;await nextTick();initialized=true;if(native&&desktopRole==='workspace'){await loadDesktopSession((await desktop.state()).sessionId)}})
onBeforeUnmount(()=>{controller?.abort();desktopDisposers.forEach(fn=>fn());if(saveTimer)clearTimeout(saveTimer);if(toastTimer)clearTimeout(toastTimer);document.removeEventListener('paste',paste);document.removeEventListener('keydown',keydown);window.removeEventListener('resize',arrangeFloating)})
</script>

<template>
 <div :class="view==='launcher'?'launcher-root launcher-toast':'floating-root'" @click="menu=''">
  <ScreenshotLauncher v-if="view==='launcher'" :model-request="modelSettingsRequest" :shortcut-request="shortcutSettingsRequest" :recent="recentCaptures" :connected="online" :capturing="capturing" :refreshing="refreshingGallery" @refresh="refreshGallery" @capture="beginScreenCapture" @import="captureInput?.click()" @gallery="galleryFilter='all';modal='gallery'" @settings="modal='settings'" @model-settings="modelSettingsRequest++" @shortcut="launcherAction('shortcut')" @preview="preview" @drop="openCaptureFiles"/>
  <main class="floating-desktop" v-if="view==='workspace'&&!loading&&active">
   <div class="floating-backdrop" v-if="desktopSource"><img :src="desktopSource.data" alt=""/></div>
   <div class="floating-desktop-nav"><span><Icon name="scan" :size="16"/>SnapMind · 浮动工作区</span><div><button class="nav-optional" @click="galleryFilter='all';modal='gallery'">截图相册</button><button class="nav-optional" @click="exportSession">导出会话</button><button aria-label="重新排列浮动窗口" title="并排排列" @click="arrangeFloating"><Icon name="panel" :size="15"/></button><button class="float-start-button" @click="beginScreenCapture"><Icon name="plus" :size="14"/>新截图</button><button @click="returnHome" aria-label="返回截图工具" title="返回截图工具"><Icon name="close" :size="15"/></button></div></div>
   <FloatingScreenshot v-if="asset&&showFloatingImage&&desktopRole!=='workspace'" :asset="asset" :x="floatImage.x" :y="floatImage.y" :width="floatImage.width" :workspace-open="showContentWorkspace" @geometry="floatImage=$event" @close="showFloatingImage=false" @edit="annotateFloating" @copy="copyFloating" @save="saveFloating" @ai="openContent" @toast="notify"/>
   <div v-else class="floating-close-placeholder">{{asset?'浮动截图已收起':'等待截图'}}<button @click="showFloatingImage=true" v-if="asset">重新显示截图</button><button @click="beginScreenCapture" v-else>开始截图</button></div>
   <section v-if="showContentWorkspace" ref="workspace" class="floating-workspace" aria-label="内容工作区" :style="{left:floatWork.x+'px',top:floatWork.y+'px',width:floatWork.width+'px',height:floatWork.height+'px'}">
    <header class="floating-workspace-titlebar floating-move-bar" @pointerdown="workDown" @pointermove="workMove" @pointerup="workDrag=false" @pointercancel="workDrag=false"><span><SnapMindLogo :size="20"/>内容工作区</span><div><small>截图 {{active.assets.length}} 张</small><button @click="modal='settings'" aria-label="内容工作区设置" data-tooltip="工作区设置"><Icon name="settings" :size="15"/></button><button aria-label="收起内容工作区" data-tooltip="收起工作区" data-tooltip-detail="浮动截图会保留，可随时重新打开工作区" @click="closeContent"><Icon name="close" :size="17"/></button></div></header>
    <div class="floating-workspace-content" @dragover.prevent @drop="drop">
    <section class="conversation-panel"><div class="panel-header"><h2><span class="ai-dot"><Icon name="sparkles" :size="15"/></span>与截图对话</h2><button class="mode-selector" @click="modal='settings'"><span class="green-dot"/>{{activeModelName||'未配置模型'}}<Icon name="down" :size="13"/></button></div>
     <div class="quick-tools"><button v-for="a in actions" :key="a.id" :disabled="busy" @click="quickAction(a.id,a.label)"><Icon :name="a.icon" :size="15"/>{{a.label}}</button></div>
     <div class="message-list" ref="messageList" aria-live="polite" aria-relevant="additions">
      <div class="conversation-start"><span>{{dateLabel(active.createdAt)}} · 截图会话</span></div>
      <div class="welcome" v-if="!active.messages.length"><span class="welcome-spark"><Icon name="sparkles" :size="29"/></span><h3>截图在旁边，内容在这里</h3><p>选择要处理的内容，或直接输入问题。<br/>截图可以随时拖动、放大，对照着继续讨论。</p><div class="welcome-examples"><button @click="quickAction('ocr','提取文字')"><Icon name="file"/>提取截图文字<Icon name="right" :size="15"/></button><button @click="quickAction('translate','翻译')"><Icon name="translate"/>翻译截图内容<Icon name="right" :size="15"/></button></div></div>
      <article v-for="m in active.messages" :key="m.id" class="message" :class="m.role"><div class="message-heading"><span class="message-avatar" :class="m.role"><Icon v-if="m.role==='assistant'" name="sparkles" :size="15"/><template v-else>我</template></span><strong>{{m.role==='assistant'?'SnapMind':'你'}}</strong><span v-if="m.demo" class="message-demo">示例回复</span></div><div class="message-body"><p class="message-text">{{m.text}}</p><template v-if="m.role==='assistant'"><div class="source-citation" v-if="m.sources?.length"><Icon name="link" :size="13"/><span>参考素材</span><button v-for="id in m.sources" :key="id" @click="assetId=id" :title="sourceName(id)">{{sourceName(id)}}<Icon name="external" :size="11"/></button></div><FormulaResult v-if="m.kind==='formula'" v-model="active.formula" @toast="notify"/><TableResult v-if="m.kind==='table'" v-model="active.rows" @toast="notify"/><div class="message-actions"><button aria-label="复制回复" title="复制回复" @click="copyText(m.text)"><Icon name="copy" :size="14"/></button><span v-if="m.demo">基于内置示例 · 请校对结果</span></div></template><div class="user-attachments" v-else-if="m.sources?.length"><button v-for="id in m.sources" :key="id" @click="assetId=id"><Icon name="images" :size="12"/>{{sourceName(id)}}</button></div></div></article>
      <article v-if="busy" class="message assistant generating"><div class="message-heading"><span class="message-avatar assistant"><Icon name="sparkles" :size="15"/></span><strong>SnapMind</strong><span class="message-demo">生成中</span></div><div class="message-body"><p v-if="streamText" class="message-text">{{streamText}}<span class="typing-cursor"/></p><div v-else class="thinking"><Icon name="loading" :size="16"/>正在等待模型回复…</div></div></article>
     </div>
     <div class="composer-area"><div class="followup-chips" v-if="active.messages.length"><span>继续探索</span><button v-for="p in suggestions" :key="p" @click="send('chat',p)" :disabled="busy">{{p}}<Icon name="link" :size="12"/></button></div><form class="composer" @submit.prevent="send()"><textarea v-model="draft" placeholder="问问截图里的内容，或继续追问…" maxlength="6000" rows="2" aria-label="对话消息" @keydown.enter.exact.prevent="send()"/><div class="composer-bottom"><div class="composer-context"><button type="button" title="追加截图" aria-label="追加截图到对话" @click="fileInput?.click()"><Icon name="attach" :size="18"/></button><span class="context-pill" v-if="active.assets.length"><Icon name="images" :size="13"/>{{active.assets.length}} 张截图作为上下文</span></div><div class="send-group"><small>Enter 发送</small><button v-if="busy" class="send-button stop" type="button" aria-label="停止生成" title="停止生成" @click="controller?.abort()"><Icon name="rect" :size="16"/></button><button v-else class="send-button" type="submit" aria-label="发送消息" :disabled="!draft.trim()||!active.assets.length"><Icon name="send" :size="18"/></button></div></div></form><p class="composer-disclaimer"><span class="green-dot"/>{{online?(activeModelName?'当前模型 · '+activeModelName:'请配置并启用 LLM 模型'):'后端未连接 · 当前内容暂存在浏览器'}}<button v-if="!online" @click="reconnect">重连</button></p></div>
    </section>
   <aside class="history-panel"><div class="panel-header"><h2><Icon name="clock" :size="17"/>历史会话</h2><span class="count">{{sessions.length}}</span></div><button class="new-session" :disabled="busy" @click="createSession()"><Icon name="plus" :size="17"/>新建会话<span>＋</span></button><label class="history-search"><Icon name="search" :size="15"/><input v-model="search" placeholder="搜索会话…" aria-label="搜索历史会话"/><button v-if="search" @click="search=''" aria-label="清空搜索"><Icon name="close" :size="12"/></button></label><div class="history-list"><p v-if="!filtered.length" class="no-results">没有找到相关会话</p><template v-for="(s,i) in filtered" :key="s.id"><p class="history-group" v-if="i===0||(s.pinned!==filtered[i-1]?.pinned)||(!s.pinned&&dateLabel(s.updatedAt)!==dateLabel(filtered[i-1]!.updatedAt))">{{s.pinned?'置顶会话':dateLabel(s.updatedAt)}}</p><div class="history-item" :class="{active:s.id===activeId}"><button class="history-select" @click="chooseSession(s)" :disabled="busy"><span class="history-icon"><Icon :name="sessionIcon(s)" :size="17"/></span><span class="history-item-text"><strong>{{s.title}}</strong><small>{{s.assets.length}} 张截图<span>·</span>{{Math.floor(s.messages.length/2)}} 轮讨论</small></span></button><button class="history-more" aria-label="会话操作" @click.stop="menu=menu===s.id?'':s.id"><Icon name="more" :size="16"/></button><div v-if="menu===s.id" class="session-menu" @click.stop><button @click="pin(s)"><Icon name="pin" :size="14"/>{{s.pinned?'取消置顶':'置顶会话'}}</button><button @click="openRename(s)"><Icon name="edit" :size="14"/>重命名</button><button @click="confirmDelete(s)" :disabled="busy" class="danger"><Icon name="trash" :size="14"/>删除会话</button></div></div></template></div><div class="history-footer"><div class="tip-card"><span class="tip-label"><Icon name="sparkles" :size="15"/>一点小提示</span><p>追加一张截图，<br/>让讨论更有上下文。</p><span class="tip-decoration"><Icon name="images" :size="39"/></span></div><div class="local-status"><Icon name="monitor" :size="14"/>本地工作空间<span><i :class="{offline:!online}"/>{{online?'已连接':'离线'}}</span></div></div></aside>
    </div><span class="floating-workspace-resize-hint"/></section>
   <div v-if="active.assets.length" class="floating-material-strip"><span>当前截图</span><button v-for="a in active.assets" :key="a.id" :class="{active:asset?.id===a.id}" :title="a.name" :aria-label="'切换浮动截图 '+a.name" @click="assetId=a.id;showFloatingImage=true"><img :src="a.data" :alt="a.name"/></button><button @click="beginScreenCapture" aria-label="追加新截图" title="追加截图"><Icon name="plus" :size="16"/></button></div>
   <span class="floating-status-hint"><Icon name="cursor" :size="13"/>拖动两个窗口的标题栏移动，拖动截图角点缩放</span>
  </main>
  <div v-else-if="view==='workspace'" class="boot-loading"><Icon name="loading" :size="25"/>正在打开你的工作空间…</div>
  <CaptureOverlay v-if="captureSource" :source="captureSource" :initial-selection="floatingPreview" :floating-preview="floatingPreview" @finish="completeCapture" @cancel="cancelCapture" @toast="notify"/>
  <div v-if="capturing" class="capture-waiting"><div><Icon name="loading" :size="18"/>在浏览器中选择要截取的屏幕或窗口</div></div>
  <div v-if="pinned" class="pinned-screenshot" :style="{left:pinPosition.x+'px',top:pinPosition.y+'px'}"><div class="pinned-title" @pointerdown="pinDown" @pointermove="pinMove" @pointerup="pinDragging=false" @pointercancel="pinDragging=false"><span><Icon name="pin" :size="12"/>贴图 · 网页内悬浮</span><button aria-label="关闭贴图" @click="pinned=undefined"><Icon name="close" :size="15"/></button></div><img :src="pinned.data" :alt="pinned.name"/></div>
  <input ref="captureInput" class="hidden-input" type="file" accept="image/png,image/jpeg,image/webp" @change="openCaptureFiles(($event.target as HTMLInputElement).files)"/>
  <input ref="fileInput" class="hidden-input" type="file" accept="image/png,image/jpeg,image/webp" multiple @change="importFiles(($event.target as HTMLInputElement).files)"/>
  <Transition name="toast"><div v-if="toast" class="toast-message" role="status"><Icon name="success" :size="17"/>{{toast}}</div></Transition>
  <div v-if="modal" class="modal-backdrop" @click.self="modal=''" @keydown.esc="modal=''">
   <section class="modal" :class="{'gallery-modal':modal==='gallery','model-settings-modal':modal==='model-settings','configuration-modal':['settings','shortcut'].includes(modal)}" role="dialog" aria-modal="true" :aria-label="tx(modal==='gallery'?'截图相册':modal==='capture'?'新截图':modal==='settings'?'设置':modal==='model-settings'?'模型配置':modal==='shortcut'?'快捷键设置':'会话操作')" tabindex="-1"><button class="modal-close" @click="modal=''" :aria-label="tx('关闭弹窗')"><Icon name="close"/></button>
    <template v-if="modal==='settings'">
     <span class="modal-symbol"><Icon name="settings" :size="25"/></span><h2>{{tx('截图工具设置')}}</h2><p>截图完成后，原图悬浮，右侧内容工作区自动出现。</p>
     <div class="screenshot-preference-grid">
     <div class="setting-row"><span><strong>完成后的布局</strong><small>独立浮动截图 + 右侧内容工作区，可分别移动和收起</small></span><span class="setting-badge">自动显示</span></div>
     <div class="setting-row"><span><strong>保存截图</strong><small>完成截图自动留存到相册；保存按钮下载 PNG</small></span><span class="setting-badge">自动留存</span></div>
     <div class="setting-row"><span><strong>本地存储</strong><small>{{online?'本机服务 · SQLite 数据库':'浏览器缓存 · 后端未连接'}}</small></span><Icon :name="online?'check':'alert'"/></div>
     <div class="setting-row"><span><strong>AI 服务</strong><small>{{activeModelName?'启用的模型：'+activeModelName:'请配置并启用 LLM 模型'}}</small></span><span class="setting-badge">{{activeModelName?'已配置':'未配置'}}</span></div>
     </div>
     <button v-if="!online" class="primary full-width" @click="reconnect">重新连接本地服务</button><div class="settings-note">{{native?'当前为桌面开发模式：截图与工作区是两个独立的 Windows 窗口，关闭窗口可在托盘恢复。':'当前悬浮和交互发生在网页内。系统级快捷键、托盘和跨窗口悬浮在桌面模式中测试。'}}</div>
    </template>
    <template v-else-if="modal==='rename'"><h2>重命名会话</h2><p>给这次讨论一个容易找回的名字。</p><form @submit.prevent="rename"><input class="title-input" v-model="editTitle" maxlength="160" aria-label="会话名称" autofocus/><div class="modal-actions"><button @click="modal=''" type="button">取消</button><button class="primary" :disabled="!editTitle.trim()">保存名称</button></div></form></template>
    <template v-else-if="modal==='delete'"><h2>删除这条会话？</h2><p>这条会话的截图、讨论和编辑结果会一并删除。</p><div class="modal-actions"><button @click="modal=''">保留会话</button><button class="danger-button" @click="remove">删除会话</button></div></template>
    <template v-else-if="modal==='gallery'"><h2>截图相册 <span class="count">{{gallery.length}}</span></h2><p>每张截图，都能找回当时的讨论。</p><div class="gallery-filters"><button v-for="f in [{id:'all',name:'全部素材'},{id:'formula',name:'论文阅读'},{id:'table',name:'办公数据'},{id:'custom',name:'导入图片'}]" :key="f.id" :class="{selected:galleryFilter===f.id}" @click="galleryFilter=f.id">{{f.name}}</button></div><div class="gallery-grid"><button v-for="item in gallery" :key="item.asset.id" class="gallery-card" @click="selectGallery(item.session,item.asset)"><img :src="item.asset.data" :alt="item.asset.name"/><strong>{{item.asset.name}}</strong><small>{{item.session.title}}</small></button><div v-if="!gallery.length" class="gallery-empty">这里还没有截图，先导入一张图片吧。</div></div></template>
   </section>
  </div>
 </div>
</template>

